drop function if exists public.history_points(uuid,date);create function public.history_points(target uuid,since date default null) returns table(id uuid,date date,title text,started_at timestamptz,weight numeric,reps integer,assistance jsonb) language sql stable security invoker set search_path='' as $$ with valid as(select w.id,w.workout_date,w.title,w.started_at,e.tracking_type,s.weight_kg,s.reps from public.workout_sessions w join public.workout_exercises we on we.session_id=w.id join public.exercises e on e.id=we.exercise_id join public.exercise_sets s on s.workout_exercise_id=we.id where e.id=target and w.user_id=auth.uid() and s.completed_at is not null and s.set_type='working' and(since is null or w.workout_date>=since)),a as(select v.id,jsonb_object_agg(v.reps::text,v.load) as values from(select valid.id,valid.reps,min(weight_kg) as load from valid where tracking_type='assisted' group by valid.id,valid.reps)v group by v.id) select v.id,v.workout_date,v.title,v.started_at,max(v.weight_kg) filter(where v.tracking_type='weighted'),max(v.reps),coalesce(a.values,'{}'::jsonb) from valid v left join a on a.id=v.id group by v.id,v.workout_date,v.title,v.started_at,a.values order by v.workout_date,v.started_at,v.id;$$;